/* ===== Page ===== */
@page {
  margin: 7.5mm;
}

@media print {
  .print-format {
    width: auto !important;
    max-width: none !important;
    min-height: 0 !important;
    padding: 0 !important;
    margin: 0 !important;
  }
}

.print-format,
.boq-doc {
  font-family: 'Noto Sans Thai', Tahoma, sans-serif !important;
  font-size: 11px;
  color: #0f172a;
  line-height: 1.3;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

/* ===== Table base ===== */
.boq-doc .boq-table {
  width: 100%;
  table-layout: fixed;
  border-collapse: separate;
  border-spacing: 0;
  margin: 0 !important;
  font-size: 11px;
}
.boq-doc .boq-table thead { display: table-header-group; }
.boq-doc .boq-table tfoot { display: table-footer-group; }

.boq-doc .boq-table th,
.boq-doc .boq-table td {
  padding: 2px 5px !important;
  vertical-align: top !important;
  line-height: 1.3;
  border: 0;
  border-right: 1px solid #000;
  border-bottom: 1px solid #e2e8f0;
  word-wrap: break-word;
  overflow-wrap: break-word;
}
.boq-doc .boq-table tr > :last-child { border-right: 0; }

/* ===== Document header ===== */
.boq-doc .boq-table th.doc-head {
  padding: 0 0 4px 0 !important;
  border: 0;
  background: #fff;
  color: #0f172a;
  text-align: left !important;
  font-weight: normal;
  font-size: 11px;
}
.doc-top {
  font-size: 0;
  border-bottom: 2px solid #0f172a;
  padding-bottom: 3px;
  margin-bottom: 4px;
}
.doc-title-block,
.doc-company {
  display: inline-block;
  vertical-align: bottom;
}
.doc-title-block { width: 60%; }
.doc-company {
  width: 40%;
  text-align: right;
  font-size: 12px;
  font-weight: 700;
}
.doc-title {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 1px;
  line-height: 1.2;
}
.doc-subtitle {
  font-size: 10px;
  color: #64748b;
  line-height: 1.25;
}

/* Meta */
.meta-box {
  background: #f1f5f9;
  border-radius: 4px;
  padding: 2px 8px;
}
.meta-line { font-size: 0; }
.meta-label,
.meta-value {
  display: inline-block;
  vertical-align: top;
  box-sizing: border-box;
  font-size: 10.5px;
  line-height: 1.5;
  white-space: normal;
  word-wrap: break-word;
  overflow-wrap: break-word;
}
.meta-label { color: #64748b; }
.meta-value { font-weight: 600; padding-right: 10px; }
.meta-label.l1 { width: 8%; }
.meta-value.v1 { width: 34%; }
.meta-label.l2 { width: 4%; }
.meta-value.v2 { width: 30%; }
.meta-label.l3 { width: 8%; }
.meta-value.v3 { width: 16%; padding-right: 0; }

/* ===== Column headers ===== */
.boq-doc .boq-table tr.col-head > th,
.boq-doc .boq-table tr.sub-head > th {
  background: #0f172a !important;
  color: #fff !important;
  font-size: 10px;
  font-weight: 700;
  text-align: center !important;
  vertical-align: middle !important;
  line-height: 1.25;
  padding: 3px 4px !important;
  border-right: 1px solid #475569;
  border-bottom: 1px solid #475569;
}
.boq-doc .boq-table tr.col-head > th:first-child { border-top-left-radius: 4px; }
.boq-doc .boq-table tr.col-head > th:last-child  { border-top-right-radius: 4px; border-right: 0; }
.boq-doc .boq-table tr.sub-head > th:last-child  { border-right: 1px solid #475569; }
.boq-doc .boq-table tr.sub-head > th { font-size: 9.5px; }

/* ===== Body cells ===== */
.boq-doc .boq-table td.c       { text-align: center; }
.boq-doc .boq-table td.wbs     { white-space: nowrap; font-size: 10px; }
.boq-doc .boq-table td.num     { text-align: right; white-space: nowrap; }
.boq-doc .boq-table td.label-r { text-align: right; }

/* ย่อหน้าตามระดับ WBS (ชื่อรายการ/หัวข้อ) */
.boq-doc .boq-table td.ind.lv2 { padding-left: 14px !important; }
.boq-doc .boq-table td.ind.lv3 { padding-left: 23px !important; }
.boq-doc .boq-table td.ind.lv4 { padding-left: 32px !important; }

/* ===== หัวข้อ + แถวรวม: ใช้พื้นหลัง/สี/ความหนา/เส้นใต้เดียวกันตามระดับ ===== */
.boq-doc .boq-table tr.grp-row > td,
.boq-doc .boq-table tr.subtotal-row > td {
  background: #cbd5e1;                  /* ระดับ 1  เช่น 1 */
  color: #0f172a;
  font-weight: 700;
  border-bottom: 1px solid #94a3b8;
}
.boq-doc .boq-table tr.grp-row.lv2 > td,
.boq-doc .boq-table tr.subtotal-row.lv2 > td {
  background: #e2e8f0;                  /* ระดับ 2  เช่น 1.1 */
  color: #0f172a;
  font-weight: 600;
  border-bottom: 1px solid #cbd5e1;
}
.boq-doc .boq-table tr.grp-row.lv3 > td,
.boq-doc .boq-table tr.subtotal-row.lv3 > td {
  background: #f1f5f9;                  /* ระดับ 3  เช่น 1.1.1 */
  color: #1e293b;
  font-weight: 600;
  border-bottom: 1px solid #cbd5e1;
}
.boq-doc .boq-table tr.grp-row.lv4 > td,
.boq-doc .boq-table tr.subtotal-row.lv4 > td {
  background: #f8fafc;                  /* ระดับ 4+ เช่น 1.1.1.1 */
  color: #334155;
  font-weight: 600;
  border-bottom: 1px solid #e2e8f0;
}
.boq-doc .boq-table tr.grp-row .desc { font-weight: 400; }

.item-name { font-weight: 400; }

/* description (Quill) */
.boq-doc .desc,
.boq-doc .desc *,
.boq-doc .desc .ql-editor {
  font-family: 'Noto Sans Thai', Tahoma, sans-serif !important;
  font-size: 9.5px !important;
  color: #64748b !important;
  line-height: 1.25 !important;
}
.boq-doc .desc p,
.boq-doc .desc ol,
.boq-doc .desc ul { margin: 0 !important; }
.boq-doc .desc ol,
.boq-doc .desc ul { padding-left: 14px !important; }
.boq-doc .desc .ql-editor { padding: 0 !important; }

/* เส้นปิดท้ายหมวด: หนาขึ้นที่แถวรวมหมวดหลัก */
.boq-doc .boq-table tr.subtotal-row > td { border-bottom: 1px solid #cbd5e1; }
.boq-doc .boq-table tr.subtotal-row.lv1 > td { border-bottom: 1px solid #64748b; }
.boq-doc .boq-table tr.subtotal-row.lv2 > td { border-bottom: 1px solid #cbd5e1; }
.boq-doc .boq-table tr.subtotal-row.lv3 > td { border-bottom: 1px solid #cbd5e1; }
.boq-doc .boq-table tr.subtotal-row.lv4 > td {
  background: #fff;
  font-weight: 600;
  font-size: 10.5px;
  color: #334155;
  border-bottom: 1px solid #cbd5e1;
}
.boq-doc .boq-table tr.subtotal-row > td.wbs {
  color: #94a3b8;
  font-weight: 400;
}
/* ขีด "-" ในแถวรวมให้คงสีเทา */
.boq-doc .boq-table tr.subtotal-row > td.dash { color: #64748b; }

/* ===== Grand total ===== */
.boq-doc .boq-table tr.grand-row > td {
  background: #0f172a;
  color: #fff;
  font-weight: 700;
  font-size: 11.5px;
  padding-top: 4px !important;
  padding-bottom: 4px !important;
  border-right: 1px solid #475569;
  border-bottom: 0;
}
.boq-doc .boq-table tr.grand-row > td:last-child { border-right: 0; }
.boq-doc .boq-table tr.grand-row > td.dash { color: #94a3b8; }

/* ===== tfoot ===== */
.boq-doc .boq-table td.foot-bar {
  height: 4px;
  padding: 0 !important;
  border: 0;
  border-radius: 0 0 4px 4px;
  background: #0f172a;
  font-size: 0;
  line-height: 0;
}

/* ===== Print ===== */
@media print {
  .boq-table > tbody > tr {
    page-break-inside: avoid;
    break-inside: avoid;
  }
  .boq-table > tbody > tr.grp-row {
    page-break-after: avoid;
    break-after: avoid;
  }
}
